    tri_seq.append(1)  # tri(2)
    for i in range(3, n + 2):
        if i % 2 == 0:
            tri_seq.append(1 + i // 2)  # Even index
        else:
            tri_seq.append(tri_seq[i - 1] + tri_seq[i - 2] + tri_seq[i + 1])  # Odd index
    return tri_seq[:i + 1]
```

