from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def depth(s: str, d: int = 0) -> int:
        """Helper function to calculate depth of nested parentheses."""
        max_depth = d
        while s:
            if s[0] == '(':
                max_depth = max(max_depth, depth(s[1:], d + 1))
            elif s[0] == ')':
                return max_depth
            s = s[1:]
        return max_depth

    return [depth(group) for group in paren_string.split()]
